      <template v-if="isTermination">
        <!-- Section T-01: Termination Details -->
        <div class="ap-section">
          <div
            class="ap-section__header"
            style="background:linear-gradient(135deg,#7f1d1d 0%,#b91c1c 100%)"
          >
            <span class="ap-section__num">01</span>
            <div>
              <div class="ap-section__title">Termination Details</div>
              <div class="ap-section__sub">
                Record the reason and effective date for ending this position
              </div>
            </div>
          </div>
          <div class="ap-section__body">
            <v-row>
              <!-- Last Working Date -->
              <v-col cols="12" sm="6">
                <v-menu
                  v-model="departureDateMenu"
                  :close-on-content-click="false"
                  max-width="290px"
                  min-width="290px"
                >
                  <template v-slot:activator="{ on, attrs }">
                    <v-text-field
                      :value="departure.lastWorkingDate"
                      label="Last Working Date"
                      outlined
                      dense
                      readonly
                      :rules="[rules.required]"
                      prepend-inner-icon="mdi-calendar-remove"
                      v-bind="attrs"
                      v-on="on"
                    />
                  </template>
                  <v-date-picker
                    v-model="departure.lastWorkingDate"
                    no-title
                    @input="departureDateMenu = false"
                  />
                </v-menu>
              </v-col>

              <!-- Reason for Termination -->
              <v-col cols="12" sm="6">
                <v-select
                  v-model="departure.reason"
                  :items="departureReasonOptions"
                  item-text="display"
                  :rules="[rules.required]"
                  label="Reason for Termination"
                  outlined
                  dense
                  return-object
                  clearable
                  prepend-inner-icon="mdi-file-document-remove-outline"
                  @change="
                    departure.dismissalReason = '';
                    departure.resignationReasons = [];
                    departure.resignationReasonOther = '';
                    departure.retirementType = null;
                    clearDepartureTransferTree();
                  "
                />
              </v-col>

              <!-- Conditional: Dismissal reason -->
              <v-col cols="12" sm="6" v-if="showDismissalField">
                <v-text-field
                  v-model="departure.dismissalReason"
                  label="Reason for Dismissal"
                  outlined
                  dense
                  :rules="[rules.required]"
                  prepend-inner-icon="mdi-gavel"
                />
              </v-col>

              <!-- Conditional: Resignation details -->
              <template v-if="showResignationDetails">
                <v-col cols="12" sm="6">
                  <v-autocomplete
                    v-model="departure.resignationReasons"
                    :items="resignationReasonOptions"
                    item-text="display"
                    :rules="[
                      (v) =>
                        (v && v.length > 0) || 'At least one reason required',
                    ]"
                    label="Resignation Reasons"
                    outlined
                    dense
                    multiple
                    return-object
                    chips
                    small-chips
                    deletable-chips
                    prepend-inner-icon="mdi-clipboard-text-outline"
                  />
                </v-col>
                <v-col cols="12" sm="6" v-if="showResignationOther">
                  <v-text-field
                    v-model="departure.resignationReasonOther"
                    label="Other Resignation Reason"
                    outlined
                    dense
                    prepend-inner-icon="mdi-pencil-outline"
                  />
                </v-col>
              </template>

              <!-- Conditional: Retirement type -->
              <v-col cols="12" sm="6" v-if="showRetirementType">
                <v-select
                  v-model="departure.retirementType"
                  :items="retirementTypeOptions"
                  item-text="display"
                  :rules="[rules.required]"
                  label="Retirement Type"
                  outlined
                  dense
                  return-object
                  clearable
                  prepend-inner-icon="mdi-human-greeting"
                />
              </v-col>

              <!-- Conditional: Transfer-out facility -->
              <v-col cols="12" sm="6" v-if="showTransferOutDetails">
                <v-menu
                  v-model="departureTransferTreeOpen"
                  :close-on-content-click="false"
                  offset-y
                  min-width="320px"
                  @input="
                    (val) => {
                      if (val) loadDepartureTransferTree();
                    }
                  "
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      :value="departureTransferTree.displayValue"
                      label="Transfer To Facility"
                      dense
                      outlined
                      clearable
                      hide-details
                      readonly
                      prepend-inner-icon="mdi-hospital-building"
                      v-on="on"
                      @click:clear="clearDepartureTransferTree"
                    />
                  </template>
                  <v-card class="ap-tree-card">
                    <v-treeview
                      :active.sync="departureTransferTree.active"
                      :items="departureTransferTree.items"
                      :load-children="fetchDepartureTransferChildren"
                      :open.sync="departureTransferTree.open"
                      activatable
                      :multiple-active="false"
                      selection-type="independent"
                      :loading="departureTransferTree.loading"
                      item-key="id"
                      dense
                      hoverable
                      open-on-click
                      @update:active="onDepartureTransferTreeActiveChange"
                    >
                      <template v-slot:label="{ item }">
                        <span class="ap-tree-label">{{ item.name }}</span>
                      </template>
                    </v-treeview>
                  </v-card>
                </v-menu>
                <div
                  v-if="
                    formSubmitted &&
                      showTransferOutDetails &&
                      !departure.transferToFacility.reference
                  "
                  class="ap-field-error mt-1"
                >
                  <v-icon size="12" color="#ef4444">mdi-alert-circle</v-icon>
                  Transfer facility is required
                </div>
              </v-col>
            </v-row>
          </div>
        </div> </template
      ><!-- /isTermination -->

      <!-- ── EXISTING FORM SECTIONS (hidden for termination) ─────────── -->
      <template v-if="!isTermination">
        <div class="ap-section">
          <div
            class="ap-section__header"
            style="background:linear-gradient(135deg,#1e3a5f 0%,#1e40af 100%)"
          >
            <span class="ap-section__num">01</span>
            <div>
              <div class="ap-section__title">Position Details</div>
              <div class="ap-section__sub">
                Assign the staff member's position and employment category
              </div>
            </div>
          </div>
          <div class="ap-section__body">
            <v-row>
              <!-- Position reference picker -->
              <v-col cols="12">
                <div class="ap-field-label">
                  Position <span class="ap-required">*</span>
                </div>
                <div
                  class="ap-ref-trigger"
                  :class="{
                    'ap-ref-trigger--filled': !!form.position.reference,
                    'ap-ref-trigger--error':
                      formSubmitted && !form.position.reference,
                  }"
                  @click="openPositionDialog"
                >
                  <template v-if="form.position.reference">
                    <v-icon size="18" color="#1e40af" class="mr-2"
                      >mdi-briefcase-check</v-icon
                    >
                    <div class="ap-ref-trigger__content">
                      <div class="ap-ref-trigger__primary">
                        {{ form.position.display }}
                      </div>
                      <div class="ap-ref-trigger__meta">
                        <span v-if="form.position.facility">
                          <v-icon size="11" color="#a8a29e"
                            >mdi-hospital-building</v-icon
                          >
                          {{ form.position.facility }}
                        </span>
                        <span
                          v-if="
                            form.position.facility && form.position.department
                          "
                          class="ap-dot"
                          >·</span
                        >
                        <span v-if="form.position.department">
                          <v-icon size="11" color="#a8a29e"
                            >mdi-tag-outline</v-icon
                          >
                          {{ form.position.department }}
                        </span>
                      </div>
                    </div>
                    <v-btn
                      icon
                      x-small
                      class="ml-auto"
                      @click.stop="clearPosition"
                    >
                      <v-icon size="14" color="#a8a29e">mdi-close</v-icon>
                    </v-btn>
                  </template>
                  <template v-else>
                    <v-icon size="16" color="#c4b5a0" class="mr-2"
                      >mdi-briefcase-search-outline</v-icon
                    >
                    <span class="ap-ref-trigger__placeholder"
                      >Click to search and select a position…</span
                    >
                    <v-icon size="16" color="#d6d3d1" class="ml-auto"
                      >mdi-chevron-right</v-icon
                    >
                  </template>
                </div>
                <div
                  v-if="formSubmitted && !form.position.reference"
                  class="ap-field-error"
                >
                  <v-icon size="12" color="#ef4444">mdi-alert-circle</v-icon>
                  Position is required
                </div>
              </v-col>

              <!-- Employment Category -->
              <v-col cols="12" sm="6">
                <v-select
                  v-model="form.employmentCategory"
                  :items="employmentCategoryOptions"
                  item-text="display"
                  :rules="[rules.required]"
                  label="Employment Category"
                  outlined
                  dense
                  return-object
                  prepend-inner-icon="mdi-account-hard-hat"
                />
              </v-col>
            </v-row>
          </div>
        </div>

        <!-- ── SECTION 02: Date of Appointment ──────────────────────────── -->
        <div class="ap-section">
          <div
            class="ap-section__header"
            style="background:linear-gradient(135deg,#0f4c5c 0%,#0e7490 100%)"
          >
            <span class="ap-section__num">02</span>
            <div>
              <div class="ap-section__title">Date of Appointment</div>
              <div class="ap-section__sub">
                Start date required · End date not applicable for permanent
                staff
              </div>
            </div>
          </div>
          <div class="ap-section__body">
            <v-row>
              <v-col cols="12" sm="6">
                <v-menu
                  v-model="startDateMenu"
                  :close-on-content-click="false"
                  max-width="290px"
                  min-width="290px"
                >
                  <template v-slot:activator="{ on, attrs }">
                    <v-text-field
                      :value="form.startDate"
                      label="Start Date"
                      outlined
                      dense
                      readonly
                      :rules="[rules.required]"
                      prepend-inner-icon="mdi-calendar-start"
                      v-bind="attrs"
                      v-on="on"
                    />
                  </template>
                  <v-date-picker
                    v-model="form.startDate"
                    no-title
                    @input="startDateMenu = false"
                  />
                </v-menu>
              </v-col>
              <v-col cols="12" sm="6" v-if="!isPermanent">
                <v-menu
                  v-model="endDateMenu"
                  :close-on-content-click="false"
                  max-width="290px"
                  min-width="290px"
                >
                  <template v-slot:activator="{ on, attrs }">
                    <v-text-field
                      :value="form.endDate"
                      label="End Date"
                      outlined
                      dense
                      readonly
                      :rules="[rules.required]"
                      prepend-inner-icon="mdi-calendar-end"
                      hint="Required for non-permanent staff"
                      persistent-hint
                      clearable
                      @click:clear="form.endDate = null"
                      v-bind="attrs"
                      v-on="on"
                    />
                  </template>
                  <v-date-picker
                    v-model="form.endDate"
                    no-title
                    :min="form.startDate"
                    @input="endDateMenu = false"
                  />
                </v-menu>
              </v-col>
            </v-row>
          </div>
        </div>

        <!-- ── SECTION 04: Supervisor ────────────────────────────────────── -->
        <div class="ap-section">
          <div
            class="ap-section__header"
            style="background:linear-gradient(135deg,#3b0764 0%,#6d28d9 100%)"
          >
            <span class="ap-section__num">04</span>
            <div>
              <div class="ap-section__title">Supervisor</div>
              <div class="ap-section__sub">
                Assign an immediate supervisor for this appointment
              </div>
            </div>
          </div>
          <div class="ap-section__body">
            <div class="ap-field-label">
              Supervisor
            </div>
            <div
              class="ap-ref-trigger"
              :class="{
                'ap-ref-trigger--filled': !!form.supervisor.reference,
                'ap-ref-trigger--error':
                  formSubmitted && !form.supervisor.reference,
                'ap-ref-trigger--purple': true,
              }"
              @click="openSupervisorDialog"
            >
              <template v-if="form.supervisor.reference">
                <v-avatar size="30" color="purple lighten-4" class="mr-3">
                  <span
                    class="ap-initials"
                    style="color:#6d28d9;font-size:11px"
                    >{{ getInitials(form.supervisor.display) }}</span
                  >
                </v-avatar>
                <div class="ap-ref-trigger__content">
                  <div class="ap-ref-trigger__primary">
                    {{ form.supervisor.display }}
                  </div>
                  <div class="ap-ref-trigger__meta">
                    <span v-if="form.supervisor.position">{{
                      form.supervisor.position
                    }}</span>
                    <span
                      v-if="
                        form.supervisor.position && form.supervisor.facility
                      "
                      class="ap-dot"
                      >·</span
                    >
                    <span v-if="form.supervisor.position">{{
                      form.supervisor.grade
                    }}</span>
                    <span
                      v-if="
                        form.supervisor.position && form.supervisor.facility
                      "
                      class="ap-dot"
                      >·</span
                    >
                    <span v-if="form.supervisor.facility">
                      <v-icon size="11" color="#a8a29e"
                        >mdi-hospital-building</v-icon
                      >
                      {{ form.supervisor.facility }}
                    </span>
                  </div>
                </div>
                <v-btn
                  icon
                  x-small
                  class="ml-auto"
                  @click.stop="clearSupervisor"
                >
                  <v-icon size="14" color="#a8a29e">mdi-close</v-icon>
                </v-btn>
              </template>
              <template v-else>
                <v-icon size="16" color="#c4b5a0" class="mr-2"
                  >mdi-account-search-outline</v-icon
                >
                <span class="ap-ref-trigger__placeholder"
                  >Click to search and select a supervisor…</span
                >
                <v-icon size="16" color="#d6d3d1" class="ml-auto"
                  >mdi-chevron-right</v-icon
                >
              </template>
            </div>
            <div
              v-if="formSubmitted && !form.supervisor.reference"
              class="ap-field-error"
            >
              <v-icon size="12" color="#ef4444">mdi-alert-circle</v-icon>
              Supervisor is required
            </div>
          </div>
        </div> </template
      ><!-- /!isTermination -->
    </v-form>
  </div>
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";

// ── FHIR extension & profile URL constants ────────────────────────────────
const DEPARTURE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/role-departure-profile";

const EXT = {
  POSITION: "http://ihris.org/fhir/StructureDefinition/position-reference",
  SUPERVISOR: "http://ihris.org/fhir/StructureDefinition/supervisor",
  EMP_CAT: "http://ihris.org/fhir/StructureDefinition/employment-category",
  // Departure / termination extensions
  DEPARTURE_DATE: "http://ihris.org/fhir/StructureDefinition/departure-date",
  DEPARTURE_REASON:
    "http://ihris.org/fhir/StructureDefinition/departure-reason",
  DISMISSAL_REASON: "http://ihris.org/fhir/StructureDefinition/dismisal-reason",
  RESIGNATION_DETAILS:
    "http://ihris.org/fhir/StructureDefinition/resignation-details",
  RETIREMENT_TYPE: "http://ihris.org/fhir/StructureDefinition/retirement-type",
  TRANSFER_OUT_DETAILS:
    "http://ihris.org/fhir/StructureDefinition/transfer-out-details",
  POS_NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
};

const VS = {
  EMP_CAT: "http://ihris.org/fhir/ValueSet/employment-category-valueset",
  DEPARTMENT: "http://ihris.org/fhir/ValueSet/departments-valueset",
  DEPARTURE_REASON: "http://ihris.org/fhir/ValueSet/departure-reason-valueset",
  RESIGNATION: "http://ihris.org/fhir/ValueSet/resignation-reason-valueset",
  RETIREMENT_TYPE: "http://ihris.org/fhir/ValueSet/retirement-type-valueset",
};

export default {
  name: "AssignPosition",
  mixins: [processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/assign-position",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-role",

      loading: false,
      saving: false,
      formValid: true,
      formSubmitted: false,

      // Date menus
      startDateMenu: false,
      endDateMenu: false,
      salaryStartMenu: false,

      // ── Form model ───────────────────────────────────────────────────
      form: {
        position: {
          reference: null,
          display: "",
          facility: "",
          department: "",
        },
        employmentCategory: null,
        startDate: null,
        endDate: null,
        supervisor: {
          reference: null,
          display: "",
          position: "",
          facility: "",
          grade: "",
        },
      },

      // ── Filter treeview (shared between picker dialogs) ───────────────
      posFilterTreeOpen: false,
      supFilterTreeOpen: false,
      filterTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {}, // 'Location/id' → { name, type: 'district'|'council'|'facility' }
        loading: false,
        displayValue: "",
      },

      // ── ValueSet option lists ─────────────────────────────────────────
      employmentCategoryOptions: [],
      departmentOptions: [],

      // ── Position picker ───────────────────────────────────────────────
      positionDialog: false,
      positionItems: [],
      positionTotal: 0,
      loadingPositions: false,
      positionOptions: { page: 1, itemsPerPage: 10, sortBy: [], sortDesc: [] },
      posFilter: { designation: "", department: null },
      posDebounce: null,

      positionHeaders: [
        { text: "Designation", value: "designation", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        { text: "Status", value: "status", sortable: false },
        { text: "Vacant / Max", value: "vacant", sortable: false, width: 130 },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],

      // ── Supervisor picker ─────────────────────────────────────────────
      supervisorDialog: false,
      supervisorItems: [],
      supervisorTotal: 0,
      loadingSupervisors: false,
      supervisorOptions: { page: 1, itemsPerPage: 10 },
      supFilter: { name: "", position: "", department: null },
      supDebounce: null,

      supervisorHeaders: [
        { text: "Name", value: "name", sortable: false },
        { text: "Position", value: "position", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        {
          text: "Employment Category",
          value: "employmentCategory",
          sortable: false,
        },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],

      practitionerName: "",
      afterSaveMessage: "",

      // ── Current role snapshot (read-only display for promotion/termination) ──
      currentRole: {
        designation: "",
        department: "",
        facility: "",
        employmentCategory: "",
        startDate: null,
        endDate: null,
        supervisor: "",
      },

      // ── Departure / termination form ──────────────────────────────────
      departureDateMenu: false,
      departure: {
        lastWorkingDate: null,
        reason: null,
        dismissalReason: "",
        resignationReasons: [],
        resignationReasonOther: "",
        retirementType: null,
        transferToFacility: { reference: null, display: "" },
      },

      // Transfer-out location treeview (termination)
      departureTransferTreeOpen: false,
      departureTransferTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },

      // Departure ValueSet options
      departureReasonOptions: [],
      resignationReasonOptions: [],
      retirementTypeOptions: [],

      rules: {
        required: (v) => !!v || "This field is required",
      },
    };
  },

  computed: {
    isEdit() {
      return !!this.queries.role && !this.isPromotion && !this.isTermination;
    },
    isPromotion() {
      return this.queries.type === "promotion";
    },
    isTermination() {
      return this.queries.type === "termination";
    },
    heroTitle() {
      if (this.isPromotion)
        return `Position Change / Promotion — ${this.practitionerName}`;
      if (this.isTermination)
        return `Contract Termination — ${this.practitionerName}`;
      return `Position Management for ${this.practitionerName}`;
    },
    heroSubtitle() {
      if (this.isPromotion)
        return "Closing current position and assigning a new one";
      if (this.isTermination)
        return "Recording reason for ending this position";
      return null;
    },
    // Departure conditional field visibility
    showDismissalField() {
      return this.departure.reason?.code === "dismissal";
    },
    showResignationDetails() {
      return this.departure.reason?.code === "resignation";
    },
    showRetirementType() {
      return this.departure.reason?.code === "retirement";
    },
    showTransferOutDetails() {
      return this.departure.reason?.code === "transferout";
    },
    showResignationOther() {
      return this.departure.resignationReasons?.some((r) => r.code === "other");
    },
    initials() {
      return this.getInitials(this.practitionerName);
    },
    isPermanent() {
      const code = (this.form.employmentCategory?.code || "").toLowerCase();
      const disp = (this.form.employmentCategory?.display || "").toLowerCase();
      return code.includes("permanent") || disp.includes("permanent");
    },
  },

  watch: {
    isPermanent(val) {
      if (val) this.form.endDate = null;
    },
    "filterTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filterTree.displayValue = id
        ? this.filterTree.treeLookup[id]?.name || id
        : "";
      this.fetchPositions();
      this.fetchSupervisors();
    },
    positionOptions: {
      handler() {
        if (this.positionDialog) this.fetchPositions();
      },
      deep: true,
    },
    supervisorOptions: {
      handler() {
        if (this.supervisorDialog) this.fetchSupervisors();
      },
      deep: true,
    },
  },

  async mounted() {
    this.loading = true;
    const baseTasks = [this.loadValueSets(), this.loadFilterTree()];
    if (this.isTermination) baseTasks.push(this.loadDepartureValueSets());
    await Promise.all(baseTasks);

    if (this.isPromotion || this.isTermination) {
      await this.loadCurrentRole();
    } else if (this.isEdit) {
      await this.loadExistingRole();
    }
    await this.loadPractitioner();
    this.loading = false;
  },

  methods: {
    async loadPractitioner() {
      try {
        const res = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const data = await res.json();
        this.practitionerName = this.parsePractitionerName(data);
      } catch (_) {
        this.practitionerName = `Practitioner/${this.queries.practitioner}`;
      }
    },

    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const nameObj = resource.name[0];
      const given = nameObj.given ? nameObj.given.join(" ") : "";
      const family = nameObj.family || "";
      return (given + " " + family).trim();
    },
    // ── ValueSets ──────────────────────────────────────────────────────
    async loadValueSets() {
      const [empCat, dept] = await Promise.all([
        this.$fhirutils.expand(VS.EMP_CAT),
        this.$fhirutils.expand(VS.DEPARTMENT),
      ]);
      this.employmentCategoryOptions = this.parseExpansion(empCat);
      this.departmentOptions = this.parseExpansion(dept);
    },

    parseExpansion(vs) {
      return (vs || []).map((c) => ({
        system: c.system,
        code: c.code,
        display: c.display,
      }));
    },

    // ── Position picker ────────────────────────────────────────────────
    openPositionDialog() {
      this.positionDialog = true;
      this.fetchPositions();
    },

    debouncedFetchPositions() {
      clearTimeout(this.posDebounce);
      this.posDebounce = setTimeout(() => {
        this.positionOptions.page = 1;
        this.fetchPositions();
      }, 350);
    },

    async fetchPositions() {
      this.loadingPositions = true;
      try {
        const params = new URLSearchParams({
          page: this.positionOptions.page,
          count: this.positionOptions.itemsPerPage,
        });
        if (this.posFilter.designation)
          params.set("designation", this.posFilter.designation);
        if (this.posFilter.department)
          params.set("department", this.posFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/report?${params}`);
        const data = await res.json();

        this.positionTotal = data.total || 0;
        this.positionItems = data.positions || [];
      } catch (err) {
        console.error("fetchPositions error", err);
      } finally {
        this.loadingPositions = false;
      }
    },

    selectPosition(item) {
      this.form.position = {
        reference: item.reference,
        display: item.designation || item.display,
        facility: item.facility,
        department: item.department,
      };
      this.positionDialog = false;
    },

    clearPosition() {
      this.form.position = {
        reference: null,
        display: "",
        facility: "",
        department: "",
      };
    },

    // ── Supervisor picker ──────────────────────────────────────────────
    openSupervisorDialog() {
      this.supervisorDialog = true;
      this.fetchSupervisors();
    },

    debouncedFetchSupervisors() {
      clearTimeout(this.supDebounce);
      this.supDebounce = setTimeout(() => {
        this.supervisorOptions.page = 1;
        this.fetchSupervisors();
      }, 350);
    },

    async fetchSupervisors() {
      this.loadingSupervisors = true;
      try {
        const params = new URLSearchParams({
          page: this.supervisorOptions.page,
          count: this.supervisorOptions.itemsPerPage,
        });
        if (this.supFilter.name) params.set("name", this.supFilter.name);
        if (this.supFilter.position)
          params.set("position", this.supFilter.position);
        if (this.supFilter.department)
          params.set("department", this.supFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();

        this.supervisorTotal = data.total || 0;
        this.supervisorItems = data.supervisors || [];
      } catch (err) {
        console.error("fetchSupervisors error", err);
      } finally {
        this.loadingSupervisors = false;
      }
    },

    selectSupervisor(item) {
      this.form.supervisor = {
        reference: item.practitionerRef,
        display: item.name,
        position: item.position,
        facility: item.facility,
        grade: item.grade,
      };
      this.supervisorDialog = false;
    },

    clearSupervisor() {
      this.form.supervisor = {
        reference: null,
        display: "",
        position: "",
        facility: "",
        grade: "",
      };
    },

    // ── Filter treeview (shared across picker dialogs) ─────────────────
    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [], // lazy-loadable
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    fetchFilterChildren(item) {
      // Called by v-treeview when expanding a node with children: []
      // Districts load councils; councils load facilities (leaf nodes)
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = []; // councils expand to facilities
            this.filterTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchFilterChildren error", err));
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    // ── Load existing role for edit ────────────────────────────────────
    async loadExistingRole() {
      try {
        const res = await fetch(`/fhir/PractitionerRole/${this.queries.role}`);
        const role = await res.json();
        this.fhirId = this.queries.role;

        const posRef = this.getExt(role, EXT.POSITION, "valueReference");
        if (posRef) {
          this.form.position = {
            reference: posRef.reference,
            display: posRef.display || "",
            facility: "",
            department: "",
          };
          // Try to enrich with position details
          try {
            const posId = posRef.reference.split("/")[1];
            const posRes = await fetch(`/fhir/Basic/${posId}`);
            const posData = await posRes.json();
            this.form.position.display =
              posData.extension?.find((e) => {
                return (
                  e.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                );
              })?.valueString || this.form.position.display;
            this.form.position.department =
              posData.extension?.find((e) => {
                return (
                  e.url ===
                  "http://ihris.org/fhir/StructureDefinition/department"
                );
              })?.valueCoding?.display || "";
            this.form.position.facility =
              posData.extension?.find((e) => {
                return (
                  e.url === "http://ihris.org/fhir/StructureDefinition/facility"
                );
              })?.valueReference?.display || "";
          } catch (err) {
            console.log(err);
          }
        }

        const empCat = this.getExt(role, EXT.EMP_CAT, "valueCoding");
        if (empCat) this.form.employmentCategory = empCat;

        this.form.startDate = role.period?.start || null;
        this.form.endDate = role.period?.end || null;

        //Get supervisor data
        const supRef = this.getExt(role, EXT.SUPERVISOR, "valueReference");
        if (supRef?.reference) {
          let response = await fetch(
            "/fhir/PractitionerRole?practitioner=" +
              supRef.reference +
              "&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition",
          );
          response = await response.json();
          let supervisorPract = response.entry.find(
            (entry) => entry.resource.resourceType === "Practitioner",
          )?.resource;
          // let supervisorRole = response.entry.find((entry) => entry.resource.resourceType === 'PractitionerRole')?.resource
          let supervisorPos = response.entry.find((entry) =>
            entry.resource.meta.profile.includes(
              "http://ihris.org/fhir/StructureDefinition/position-profile",
            ),
          )?.resource;
          let designationId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/designation"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          if (designationId) {
            response = await fetch("/fhir/Basic/" + designationId);
            response = await response.json();
            this.form.supervisor.position =
              response?.extension?.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                );
              })?.valueString || "";
          }

          let facilityId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url === "http://ihris.org/fhir/StructureDefinition/facility"
              );
            })
            ?.valueReference?.reference?.split("/")?.[1];
          if (facilityId) {
            response = await fetch("/fhir/Location/" + facilityId);
            response = await response.json();
            this.form.supervisor.facility = response.name;
          }

          let gradeId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/salary-grade"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          if (gradeId) {
            response = await fetch("/fhir/Basic/" + gradeId);
            response = await response.json();
            this.form.supervisor.grade = response?.extension?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString;
          }

          if (supervisorPract?.name?.length) {
            let nameObj = supervisorPract.name[0];
            let given = nameObj.given ? nameObj.given.join(" ") : "";
            let family = nameObj.family || "";
            this.form.supervisor.display = (given + " " + family).trim();
          }
          if (supRef) {
            this.form.supervisor.reference = supRef.reference;
          }
          // end of supervisor data
        }
      } catch (err) {
        console.error("loadExistingRole error", err);
      }
    },

    // ── Submit ─────────────────────────────────────────────────────────
    async submit() {
      const valid = this.$refs.form.validate();
      let roleId = this.queries.role;
      if (this.isPromotion) {
        roleId = null;
      }

      this.formSubmitted = true;
      if (!valid) return;

      this.saving = true;
      try {
        if (this.isTermination) {
          this.fhir.termination = this.buildTermination();
          this.url = "http://ihris.org/fhir/Questionnaire/terminate-position";
        } else {
          this.fhir = {
            isPromotion: this.isPromotion,
            role: roleId,
            position: this.form.position.reference,
            startDate: this.form.startDate,
            endDate: this.isPermanent ? null : this.form.endDate || null,
            employmentCategory: this.form.employmentCategory,
            supervisor: this.form.supervisor.reference,
          };
        }
        if (roleId) {
          this.afterSaveMessage = "Position updated successfully";
        } else if (this.isPromotion) {
          this.afterSaveMessage = "Promotion recorded successfully";
        } else {
          this.afterSaveMessage = "Position assigned successfully";
        }
        await this.processFHIR();
        if (this.isTermination) {
          this.$router.push(
            `/resource/view/practitioner/${this.queries.practitioner}`,
          );
        } else {
          this.$router.push(
            `/custom/view-position?path=/lesotho/components/position&practitioner=${this.queries.practitioner}&role=${this.fhirId}`,
          );
        }
      } catch (err) {
        console.error("submit error", err);
      } finally {
        this.saving = false;
      }
    },

    // ── Termination submit ─────────────────────────────────────────────
    buildTermination() {
      // 2. Build departure Basic resource
      const extensions = [
        {
          url: EXT.DEPARTURE_DATE,
          valueDate: this.departure.lastWorkingDate,
        },
        {
          url: EXT.DEPARTURE_REASON,
          valueCoding: this.departure.reason,
        },
      ];

      if (this.showDismissalField && this.departure.dismissalReason) {
        extensions.push({
          url: EXT.DISMISSAL_REASON,
          valueString: this.departure.dismissalReason,
        });
      }

      if (
        this.showResignationDetails &&
        this.departure.resignationReasons.length
      ) {
        const subExts = this.departure.resignationReasons.map((r) => ({
          url: "resignation-reason",
          valueCoding: r,
        }));
        if (
          this.showResignationOther &&
          this.departure.resignationReasonOther
        ) {
          subExts.push({
            url: "resignation-reason-other",
            valueString: this.departure.resignationReasonOther,
          });
        }
        extensions.push({ url: EXT.RESIGNATION_DETAILS, extension: subExts });
      }

      if (this.showRetirementType && this.departure.retirementType) {
        extensions.push({
          url: EXT.RETIREMENT_TYPE,
          valueCoding: this.departure.retirementType,
        });
      }

      if (
        this.showTransferOutDetails &&
        this.departure.transferToFacility.reference
      ) {
        extensions.push({
          url: EXT.TRANSFER_OUT_DETAILS,
          extension: [
            {
              url: "facility",
              valueReference: {
                reference: this.departure.transferToFacility.reference,
              },
            },
          ],
        });
      }

      // practitionerrole reference extension
      extensions.push({
        url:
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-role",
        valueReference: {
          reference: `PractitionerRole/${this.queries.role}`,
        },
      });

      const body = {
        resourceType: "Basic",
        meta: { profile: [DEPARTURE_PROFILE] },
        extension: extensions,
      };
      return body;
    },

    // ── Load current role for read-only display (promotion / termination) ─
    async loadCurrentRole() {
      try {
        const res = await fetch(
          `/site/position/getCurrentRole/${this.queries.practitioner}`,
        );
        let role = await res.json();
        if (!role) {
          this.$router.go(-1);
          return;
        }
        if (role.period.end && this.isTermination) {
          this.$router.go(-1);
          return;
        }

        const empCat = this.getExt(role, EXT.EMP_CAT, "valueCoding");
        this.currentRole.employmentCategory =
          empCat?.display || empCat?.code || "";
        this.currentRole.startDate = role.period?.start || null;
        this.currentRole.endDate = role.period?.end || null;

        // Facility from role.location[0]
        const facilityRef = role.location?.[0]?.reference;
        if (facilityRef) {
          try {
            const fRes = await fetch(`/fhir/${facilityRef}`);
            const fData = await fRes.json();
            this.currentRole.facility = fData.name || facilityRef;
          } catch (_) {
            this.currentRole.facility = facilityRef;
          }
        }

        // Position Basic → designation + department
        const posRef = this.getExt(role, EXT.POSITION, "valueReference");
        if (posRef?.reference) {
          try {
            const posId = posRef.reference.split("/")[1];
            const posRes = await fetch(`/fhir/Basic/${posId}`);
            const posData = await posRes.json();
            // designation via designation extension → another Basic
            const desigRef = posData.extension?.find(
              (e) =>
                e.url ===
                "http://ihris.org/fhir/StructureDefinition/designation",
            )?.valueReference;
            if (desigRef?.reference) {
              try {
                const dId = desigRef.reference.split("/")[1];
                const dRes = await fetch(`/fhir/Basic/${dId}`);
                const dData = await dRes.json();
                this.currentRole.designation =
                  this.getExt(dData, EXT.POS_NAME, "valueString") ||
                  desigRef.display ||
                  "";
              } catch (_) {
                this.currentRole.designation = desigRef.display || "";
              }
            }
            const deptCoding = posData.extension?.find(
              (e) =>
                e.url ===
                "http://ihris.org/fhir/StructureDefinition/department",
            )?.valueCoding;
            this.currentRole.department =
              deptCoding?.display || deptCoding?.code || "";
          } catch (err) {
            console.log(err);
          }
        }

        // Supervisor name
        const supRef = this.getExt(role, EXT.SUPERVISOR, "valueReference");
        if (supRef?.reference) {
          try {
            const supId = supRef.reference.split("/")[1];
            const supRes = await fetch(`/fhir/Practitioner/${supId}`);
            const supData = await supRes.json();
            if (supData.name?.length) {
              const n = supData.name[0];
              const given = (n.given || []).join(" ");
              const family = n.family || "";
              this.currentRole.supervisor = (given + " " + family).trim();
            }
          } catch (err) {
            console.log(err);
          }
        }
      } catch (err) {
        console.error("loadCurrentRole error", err);
      }
    },

    // ── Departure ValueSets ────────────────────────────────────────────
    async loadDepartureValueSets() {
      const [depReason, resignReason, retType] = await Promise.all([
        this.$fhirutils.expand(VS.DEPARTURE_REASON),
        this.$fhirutils.expand(VS.RESIGNATION),
        this.$fhirutils.expand(VS.RETIREMENT_TYPE),
      ]);
      this.departureReasonOptions = this.parseExpansion(depReason);
      this.resignationReasonOptions = this.parseExpansion(resignReason);
      this.retirementTypeOptions = this.parseExpansion(retType);
    },

    // ── Transfer-out location tree (for departure) ─────────────────────
    async loadDepartureTransferTree() {
      if (this.departureTransferTree.items.length) return;
      this.departureTransferTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [],
        }));
        nodes.forEach((n) => {
          this.departureTransferTree.treeLookup[n.id] = {
            name: n.name,
            type: "district",
          };
        });
        this.departureTransferTree.items = nodes;
      } catch (err) {
        console.error("loadDepartureTransferTree error", err);
      } finally {
        this.departureTransferTree.loading = false;
      }
    },

    fetchDepartureTransferChildren(item) {
      const parentInfo = this.departureTransferTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = [];
            this.departureTransferTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) =>
          console.error("fetchDepartureTransferChildren error", err),
        );
    },

    clearDepartureTransferTree() {
      this.departureTransferTree.active = [];
      this.departureTransferTree.open = [];
      this.departureTransferTree.displayValue = "";
      this.departure.transferToFacility = { reference: null, display: "" };
    },

    onDepartureTransferTreeActiveChange(val) {
      const id = val && val.length ? val[0] : null;
      if (!id) {
        this.departureTransferTree.displayValue = "";
        this.departure.transferToFacility = { reference: null, display: "" };
        return;
      }
      const info = this.departureTransferTree.treeLookup[id];
      if (info?.type !== "facility") return;
      const name = info.name || id;
      this.departureTransferTree.displayValue = name;
      this.departure.transferToFacility = { reference: id, display: name };
      this.departureTransferTreeOpen = false;
    },

    // ── Helpers ────────────────────────────────────────────────────────
    getExt(resource, url, type) {
      const ext = resource?.extension?.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },

    getInitials(name = "") {
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((w) => w[0].toUpperCase())
        .join("");
    },
  },
};
</script>

